"""Built-in practice datasets, generated by code (so there is nothing to download and no licence to worry about)."""

from __future__ import annotations

import csv
import io
import math
from pathlib import Path

import numpy as np

SAMPLES = {
    "houses": {"title": "House prices", "icon": "🏠", "kind": "table", "target": "price",
               "about": "2,000 made-up houses: size, rooms, age, area, garden… Predict the price (a number)."},
    "spirals": {"title": "Two spirals", "icon": "🌀", "kind": "table", "target": "arm",
                "about": "Points on two interleaved spirals. A straight line cannot separate them; a model that learns curves can."},
    "reviews": {"title": "Product reviews", "icon": "💬", "kind": "table", "target": "sentiment",
                "about": "1,600 short reviews. Learn from the words whether a review is positive or negative."},
    "code": {"title": "Python code", "icon": "🐍", "kind": "text",
             "about": "AI Room's own source code (about 1 MB). The model learns to write text that looks like it."},
}


def _csv(header: list[str], rows: list[list]) -> bytes:
    buf = io.StringIO()
    w = csv.writer(buf)
    w.writerow(header)
    w.writerows(rows)
    return buf.getvalue().encode()


def houses(n: int = 2000, seed: int = 7) -> bytes:
    rng = np.random.default_rng(seed)
    areas = {"Riverside": 1.35, "Old Town": 1.2, "Hillcrest": 1.1, "Parkview": 1.0, "Station": 0.92, "Industrial": 0.75}
    names = list(areas)
    rows = []
    for _ in range(n):
        area = names[rng.integers(len(names))]
        size = float(np.clip(rng.normal(110, 40), 30, 320))
        rooms = int(np.clip(round(size / 30 + rng.normal(0, 0.8)), 1, 8))
        age = int(np.clip(rng.exponential(25), 0, 120))
        dist = float(np.clip(rng.gamma(2.2, 2.5), 0.2, 30))
        garden = rng.random() < (0.25 + 0.5 * (dist > 4))
        cond = ["poor", "fair", "good", "excellent"][int(np.clip(rng.normal(2 - age / 60, 0.9), 0, 3))]
        price = (2600 * size ** 0.92 * areas[area] * (1 + 0.12 * ["poor", "fair", "good", "excellent"].index(cond))
                 * math.exp(-dist / 22) * (1.07 if garden else 1.0) * (1 - min(age, 80) / 400) + 9000 * rooms)
        price *= math.exp(rng.normal(0, 0.08))
        built = 2025 - age
        rows.append([round(size), rooms, built, area, round(dist, 1), "yes" if garden else "no", cond,
                     "" if rng.random() < 0.03 else int(round(price, -3))])
    return _csv(["size_m2", "bedrooms", "year_built", "area", "km_to_center", "garden", "condition", "price"], rows)


def spirals(n: int = 1200, seed: int = 3) -> bytes:
    rng = np.random.default_rng(seed)
    rows = []
    for i in range(n):
        arm = i % 2
        t = rng.uniform(0.25, 3.2) * math.pi
        r = t / (3.2 * math.pi)
        a = t + arm * math.pi
        rows.append([round(r * math.cos(a) + rng.normal(0, 0.025), 4), round(r * math.sin(a) + rng.normal(0, 0.025), 4), "A" if arm == 0 else "B"])
    return _csv(["x", "y", "arm"], rows)


_GOOD = ["great", "excellent", "lovely", "sturdy", "fast", "comfortable", "reliable", "beautiful", "perfect", "brilliant", "handy", "quiet"]
_BAD = ["terrible", "flimsy", "slow", "broken", "noisy", "disappointing", "cheap", "useless", "awful", "faulty", "uncomfortable", "ugly"]
_THINGS = ["kettle", "backpack", "lamp", "phone case", "chair", "blender", "headphones", "tent", "jacket", "keyboard", "water bottle", "umbrella"]
_PARTS = ["battery", "handle", "zip", "screen", "lid", "strap", "button", "cable", "fabric", "motor", "seal", "box"]


def reviews(n: int = 1600, seed: int = 11) -> bytes:
    rng = np.random.default_rng(seed)
    pick = lambda xs: xs[rng.integers(len(xs))]
    rows = []
    for _ in range(n):
        pos = rng.random() < 0.5
        mood, other = (_GOOD, _BAD) if pos else (_BAD, _GOOD)
        thing = pick(_THINGS)
        parts = [f"The {thing} is {pick(mood)}.",
                 f"The {pick(_PARTS)} feels {pick(mood)}." if rng.random() < 0.7 else f"The {pick(_PARTS)} is not {pick(other)}.",
                 pick(["Would buy again.", "Five stars.", "Recommended to friends."] if pos else ["Sent it back.", "One star.", "Avoid it."])
                 if rng.random() < 0.6 else "",
                 f"Only the {pick(_PARTS)} is a bit {pick(other)}." if rng.random() < 0.35 else ""]
        rng.shuffle(parts)
        text = " ".join(p for p in parts if p)
        if rng.random() < 0.05:          # a few mislabelled rows, like real data
            pos = not pos
        rows.append([text, "positive" if pos else "negative"])
    return _csv(["review", "sentiment"], rows)


def code() -> bytes:
    root = Path(__file__).resolve().parent.parent
    parts = []
    for p in sorted(root.rglob("*.py")):
        parts.append(f"# file: {p.relative_to(root.parent).as_posix()}\n" + p.read_text(encoding="utf-8", errors="replace"))
    return "\n\n".join(parts).encode()


def make(name: str) -> tuple[str, bytes]:
    """(filename, contents) for a sample."""
    if name == "houses":
        return "house_prices.csv", houses()
    if name == "spirals":
        return "two_spirals.csv", spirals()
    if name == "reviews":
        return "product_reviews.csv", reviews()
    if name == "code":
        return "ai_room_code.txt", code()
    raise KeyError(name)
